('window function Meaning', 'In SQL Basics (HARD), which statement best describes window function?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["A function that computes values over a window of rows without collapsing rows","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A function that computes values over a window of rows without collapsing rows'),
('window function Use Case', 'When should you use window function while solving SQL Basics problems?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Use it for rankings, running totals, and per-row analytics","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it for rankings, running totals, and per-row analytics'),
('window function Pitfall', 'Which mistake is most closely related to window function?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Expecting window functions to reduce result rows like GROUP BY","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Expecting window functions to reduce result rows like GROUP BY'),
('window function Example', 'Which example correctly demonstrates window function?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["RANK() OVER (PARTITION BY dept ORDER BY salary DESC)","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'RANK() OVER (PARTITION BY dept ORDER BY salary DESC)'),
('CTE Meaning', 'In SQL Basics (HARD), which statement best describes CTE?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["A named temporary result set introduced with WITH for a single SQL statement","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A named temporary result set introduced with WITH for a single SQL statement'),
('CTE Use Case', 'When should you use CTE while solving SQL Basics problems?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Use it to make complex queries readable and reusable within one statement","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it to make complex queries readable and reusable within one statement'),
('CTE Pitfall', 'Which mistake is most closely related to CTE?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Assuming a non-materialized CTE is always faster than an inline subquery","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Assuming a non-materialized CTE is always faster than an inline subquery'),
('CTE Example', 'Which example correctly demonstrates CTE?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["WITH HighEarners AS (SELECT * FROM Employees WHERE salary > 80000) SELECT * FROM HighEarners;","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'WITH HighEarners AS (SELECT * FROM Employees WHERE salary > 80000) SELECT * FROM HighEarners;'),
('recursive CTE Meaning', 'In SQL Basics (HARD), which statement best describes recursive CTE?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["A CTE that references itself to process hierarchical or graph-like data","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A CTE that references itself to process hierarchical or graph-like data'),
('recursive CTE Use Case', 'When should you use recursive CTE while solving SQL Basics problems?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Use it for org charts, category trees, or bill-of-material paths","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it for org charts, category trees, or bill-of-material paths'),
('recursive CTE Pitfall', 'Which mistake is most closely related to recursive CTE?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Forgetting a termination condition and creating runaway recursion","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Forgetting a termination condition and creating runaway recursion'),
('recursive CTE Example', 'Which example correctly demonstrates recursive CTE?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["WITH RECURSIVE tree AS (...) SELECT * FROM tree;","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'WITH RECURSIVE tree AS (...) SELECT * FROM tree;'),
('EXPLAIN Meaning', 'In SQL Basics (HARD), which statement best describes EXPLAIN?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["A statement that displays the query execution plan chosen by the optimizer","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A statement that displays the query execution plan chosen by the optimizer'),
('EXPLAIN Use Case', 'When should you use EXPLAIN while solving SQL Basics problems?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Use it to inspect scans, joins, and index usage before tuning","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it to inspect scans, joins, and index usage before tuning'),
('EXPLAIN Pitfall', 'Which mistake is most closely related to EXPLAIN?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Reading estimated plans as exact runtime facts without EXPLAIN ANALYZE","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Reading estimated plans as exact runtime facts without EXPLAIN ANALYZE'),
('EXPLAIN Example', 'Which example correctly demonstrates EXPLAIN?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["EXPLAIN SELECT * FROM Orders WHERE customer_id = 7;","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'EXPLAIN SELECT * FROM Orders WHERE customer_id = 7;'),
('LATERAL join Meaning', 'In SQL Basics (HARD), which statement best describes LATERAL join?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["A join that lets a subquery reference columns from earlier FROM items","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A join that lets a subquery reference columns from earlier FROM items'),
('LATERAL join Use Case', 'When should you use LATERAL join while solving SQL Basics problems?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Use it for per-row top-N lookups or correlated row expansion","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it for per-row top-N lookups or correlated row expansion'),
('LATERAL join Pitfall', 'Which mistake is most closely related to LATERAL join?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["Using it where a simple join is enough and making the query harder to read","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Using it where a simple join is enough and making the query harder to read'),
('LATERAL join Example', 'Which example correctly demonstrates LATERAL join?', 'MCQ', 'HARD', 'DBMS', 'SQL Basics', '["JOIN LATERAL (SELECT * FROM Orders o WHERE o.customer_id = c.id LIMIT 1) x ON true","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'JOIN LATERAL (SELECT * FROM Orders o WHERE o.customer_id = c.id LIMIT 1) x ON true'),
('Rank Salary', 'Rank employees by salary inside each department.', 'CODING', 'HARD', 'DBMS', 'SQL Basics', NULL, 'SELECT name, dept, RANK() OVER (PARTITION BY dept ORDER BY salary DESC) AS dept_rank FROM Employees;'),
('CTE High Earners', 'Use a CTE HighEarners for employees with salary above 80000 then count by dept.', 'CODING', 'HARD', 'DBMS', 'SQL Basics', NULL, 'WITH HighEarners AS (SELECT * FROM Employees WHERE salary > 80000) SELECT dept, COUNT(*) FROM HighEarners GROUP BY dept;'),
