('normalization Meaning', 'In Normalization (EASY), which statement best describes normalization?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["The process of organizing relational data to reduce redundancy and anomalies","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'The process of organizing relational data to reduce redundancy and anomalies'),
('normalization Use Case', 'When should you use normalization while solving Normalization problems?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["Use it when designing schemas that should avoid duplicated facts","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it when designing schemas that should avoid duplicated facts'),
('normalization Pitfall', 'Which mistake is most closely related to normalization?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["Splitting tables mechanically without preserving needed relationships","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Splitting tables mechanically without preserving needed relationships'),
('normalization Example', 'Which example correctly demonstrates normalization?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["Move repeated customer data from Orders into Customers","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'Move repeated customer data from Orders into Customers'),
('1NF Meaning', 'In Normalization (EASY), which statement best describes 1NF?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["A normal form requiring atomic column values and unique rows","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A normal form requiring atomic column values and unique rows'),
('1NF Use Case', 'When should you use 1NF while solving Normalization problems?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["Use it to remove repeating groups and multi-valued cells","Use it only after the program has already terminated","Use it to avoid defining clear input and output boundaries","Use it when correctness does not depend on state or ordering"]', 'Use it to remove repeating groups and multi-valued cells'),
('1NF Pitfall', 'Which mistake is most closely related to 1NF?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["Storing comma-separated lists in a single column","Assuming it always has zero cost and no side effects","Using it without checking whether the input data matches the assumption","Treating all implementations as identical in every database or operating system"]', 'Storing comma-separated lists in a single column'),
('1NF Example', 'Which example correctly demonstrates 1NF?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["Store one phone number per row instead of phone1, phone2, phone3","A comment that says the code is correct","A variable name chosen because it looks readable","A command or query that does not reference the concept"]', 'Store one phone number per row instead of phone1, phone2, phone3'),
('2NF Meaning', 'In Normalization (EASY), which statement best describes 2NF?', 'MCQ', 'EASY', 'DBMS', 'Normalization', '["A normal form where every non-key attribute depends on the whole composite key","It is only a visual formatting convention and has no runtime meaning","It is a compiler-only feature that never affects execution","It is used only for documentation and cannot change program behavior"]', 'A normal form where every non-key attribute depends on the whole composite key'),
