('Deadlock Retry Comment', 'Write SQL comment describing retry after deadlock.', 'CODING', 'HARD', 'DBMS', 'Transactions', NULL, '-- On deadlock: ROLLBACK and retry the entire transaction from the beginning'),
('Prepare Transaction', 'Write PostgreSQL prepared transaction command named tx1.', 'CODING', 'HARD', 'DBMS', 'Transactions', NULL, 'PREPARE TRANSACTION ''tx1'';'),
('Commit Prepared', 'Write PostgreSQL command to commit prepared transaction tx1.', 'CODING', 'HARD', 'DBMS', 'Transactions', NULL, 'COMMIT PREPARED ''tx1'';');

